standard_spill.sql:
SET threads=1; SET memory_limit='64MB';
SET preserve_insertion_order=false; SET temp_directory='$SPILL_DIR/spill';
SET enable_profiling='json'; SET profiling_output='$SPILL_DIR/profile.json';
COPY (SELECT DISTINCT ((hash(i % 8000000) & 9223372036854775807::UBIGINT) << 1) AS k
FROM range(16000000) t(i) ORDER BY k) TO '$SPILL_DIR/keys.csv' (HEADER false);
